mapper.update:
UPDATE inventory SET
        quantity=quantity+#{quantity},version=version+1,updated_at=CURRENT_TIMESTAMP,updated_by='SYSTEM' WHERE id=#{id}
        AND version=#{version} AND deleted=FALSE

mapper.select:
SELECT * FROM
        inventory WHERE deleted=FALSE
        AND warehouse_id=#{warehouseId}
        AND sku_id=#{skuId}
        ORDER BY updated_at DESC,id DESC
